def spiral(center, bounds=(11,11), start='up', steps=20):
    r,c=center; out={(r,c)}
    dirs={'up':(-1,0),'right':(0,1),'down':(1,0),'left':(0,-1)}
    # directions cycle from chosen, segment lengths 2,2,4,4,...
    dorder=['up','right','down','left']
    idx=dorder.index(start)
    n=2
    for k in range(steps):
        dr,dc=dirs[dorder[idx%4]]
        for _ in range(n):
            r+=dr;c+=dc
            if 0<=r<bounds[0] and 0<=c<bounds[1]: out.add((r,c))
            else: return out
        idx+=1
        if k%2==1: n+=2
    return out
